#include "interface.h"

void visual_aplicar(void) {
    GtkCssProvider *css = gtk_css_provider_new();
    gtk_css_provider_load_from_string(css,
        "window, window label, window button, window entry { font-family: 'Segoe UI', 'Inter', Arial, sans-serif; font-size: 16px; font-weight: 500; }"
        "window { background: #f1f5f9; color: #0f172a; }"
        "window .menu-lateral { background: #10192b; border-right: 1px solid rgba(15, 23, 42, 0.12); padding-top: 20px; }"
        "window .faixa-vermelha { min-height: 0; margin: 0; background: transparent; }"
        "window .logo-selo { background: transparent; padding: 0; margin: 0; }"
        "window .logo { font-family: 'Segoe UI', 'Inter', Arial, sans-serif; font-size: 32px; font-weight: 800; color: #ffffff; padding: 0; }"
        "window .sublogo { color: #94a3b8; font-size: 13.5px; font-weight: 600; padding: 0; }"
        "window button.menu { margin: 3px 14px; padding: 13px 16px; border: none; border-radius: 12px; background: transparent; color: #cbd5e1; box-shadow: none; }"
        "window button.menu label { font-size: 17px; font-weight: 600; color: #cbd5e1; }"
        "window button.menu:hover { background: rgba(255, 255, 255, 0.08); }"
        "window button.menu:checked { background: #2563eb; color: #ffffff; border-left: none; }"
        "window button.menu:checked label { color: #ffffff; font-weight: 700; }"
        "window .perfil-box { margin: 16px 18px 20px 18px; }"
        "window .avatar-perfil { background: #19253d; color: #e2e8f0; border-radius: 99px; padding: 10px; }"
        "window .usuario-nome { color: #ffffff; font-weight: 700; font-size: 16px; }"
        "window .usuario-info { color: #94a3b8; font-size: 14px; font-weight: 500; }"
        "window .titulo, window .titulo-form { font-family: 'Segoe UI', 'Inter', Arial, sans-serif; font-size: 36px; font-weight: 800; color: #0f172a; }"
        "window .subtitulo, window .nota-busca, window .motivo { color: #475569; font-size: 16px; font-weight: 600; }"
        "window .secao, window .titulo-resultado, window .nome-sala-busca { font-family: 'Segoe UI', 'Inter', Arial, sans-serif; font-size: 22px; font-weight: 700; color: #0f172a; }"
        "window .numero-grande, window .numero-busca { font-family: 'Segoe UI', 'Inter', Arial, sans-serif; font-size: 38px; font-weight: 800; color: #0f172a; }"
        "window .cartao-info, window .painel-lista, window .cartao-sala, window .form-busca, window .form-salas, window .painel-verif, window .card-visao { background: #ffffff; background-image: none; border: 1px solid #cbd5e1; border-radius: 16px; padding: 20px 22px; }"
        "window .cartao-conflito { border: 2px solid #dc2626; }"
        "window .icone-cartao { background: #dbeafe; color: #2563eb; border-radius: 12px; padding: 12px; }"
        "window .icone-cartao.sucesso { background: #d1fae5; color: #059669; }"
        "window .badge-sala, window .tag-tipo, window .badge { background: #e2e8f0; color: #1e293b; font-weight: 800; font-size: 14px; padding: 5px 12px; border-radius: 9px; min-width: 82px; }"
        "window .cabecalho-tabela, window .cabecalho-tabela label, window .cab-reservas label { color: #64748b; font-size: 13px; font-weight: 700; letter-spacing: 0.8px; }"
        "window .link-ver-todas, window .link-ver-todas label { color: #2563eb; font-size: 15px; font-weight: 700; background: transparent; border: none; box-shadow: none; padding: 0; }"
        "window .link-ver-todas:hover label { color: #1d4ed8; text-decoration: underline; }"
        "window button.primario { background: #2563eb; background-image: none; color: #ffffff; border: none; border-radius: 12px; padding: 13px 24px; box-shadow: none; }"
        "window button.primario label { color: #ffffff; font-weight: 700; font-size: 16px; }"
        "window button.primario:hover { background: #1d4ed8; }"
        "window button.secundario, window button.btn-pdf, window button.btn-csv, window menubutton > button { background: #ffffff; background-image: none; color: #0f172a; border: 1px solid #cbd5e1; border-radius: 10px; padding: 10px 18px; box-shadow: none; }"
        "window button.secundario label, window button.btn-pdf label, window button.btn-csv label, window menubutton > button label { color: #0f172a; font-weight: 600; font-size: 16px; }"
        "window button.secundario:hover, window button.btn-pdf:hover, window button.btn-csv:hover, window menubutton > button:hover { background: #e2e8f0; }"
        "window entry, window spinbutton, window passwordentry, window dropdown > button, window .seletor-data { background: #ffffff; background-image: none; color: #0f172a; border: 1px solid #cbd5e1; border-radius: 10px; font-weight: 600; }"
        "window scrolledwindow, window viewport, window frame, window stack, window .moldura, window .moldura-reservas { background: transparent; border-color: #cbd5e1; }"
        "window .tabela-salas, window .tab-reservas { background: #ffffff; border-radius: 14px; }"
        "window .tabela-salas row, window .tab-reservas row { background: transparent; color: #0f172a; border-bottom: 1px solid #e2e8f0; }"
        "window .tabela-salas row label, window .tab-reservas row label { color: #0f172a; font-weight: 600; }"
        "window .tabela-salas row:hover, window .tab-reservas row:hover { background: #f1f5f9; }"
        "window .tabela-salas row:selected, window .tab-reservas row:selected { background: #2563eb; color: #ffffff; }"
        "window .tabela-salas row:selected label, window .tab-reservas row:selected label { color: #ffffff; }"
        "window .linha-info, window .linha-quadro, window .linha-ocup, window .resumo-linha { padding: 13px 0; border-bottom: 1px solid #e2e8f0; color: #0f172a; }"
        "window .linha-info label { color: #0f172a; font-size: 16px; font-weight: 600; }"
        "window .negrito { font-weight: 700; color: #0f172a; }"
        "window .texto-destaque { color: #334155; font-size: 16px; font-weight: 600; }"
        "window .cab-quadro, window .bloco-hora { background: #e2e8f0; color: #0f172a; border-radius: 10px; }"
        "window .cab-quadro label, window .bloco-hora label { color: #0f172a; font-weight: 700; }"
        "window notebook, window notebook > header, window notebook > header > tabs, window notebook > stack { background: transparent; border-color: #cbd5e1; }"
        "window notebook > header > tabs > tab { color: #475569; font-weight: 700; padding: 10px 16px; }"
        "window notebook > header > tabs > tab:checked { color: #0f172a; border-bottom: 2px solid #2563eb; }"
        "window .barra-status { margin: 10px 36px 18px 36px; padding: 12px 18px; border-radius: 12px; border: 1px solid #cbd5e1; background: #ffffff; color: #0f172a; }"
        "window .barra-status label { color: #0f172a; font-size: 15px; font-weight: 600; }"
        "window .barra-status.success { background: #dcfce7; border-color: #22c55e; color: #14532d; }"
        "window .barra-status.error { background: #fee2e2; border-color: #ef4444; color: #7f1d1d; }"
        "window .status-ponto { color: #16a34a; font-size: 14px; }"
    );
    gtk_style_context_add_provider_for_display(gdk_display_get_default(),
        GTK_STYLE_PROVIDER(css), GTK_STYLE_PROVIDER_PRIORITY_USER);
    g_object_unref(css);
}
